import java.util.*;

class Solution {
    public boolean subsetSumExists(int[] nums, int target) {
        return dfs(nums, 0, target);
    }

    private boolean dfs(int[] nums, int index, int remaining) {
        if (remaining == 0) {
            return true;
        }
        if (index == nums.length || remaining < 0) {
            return false;
        }
        return dfs(nums, index + 1, remaining - nums[index]) || dfs(nums, index + 1, remaining);
    }
}
